insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='isra-wal-miraj'),'conclusion',1,'Thirteen indexed records (Bukhārī 5, Muslim 3, Nasāʾī 3, Ibn Mājah 1, Tirmidhī 1) form three transmission branches through Anas b. Mālik: from Mālik b. Ṣaʿṣaʿa (5), from Abū Dharr (3), and Anas reporting directly (5). They are not 13 independent witnesses.',array['bukhari:3887','bukhari:349','muslim:162a']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='isra-wal-miraj'),'conclusion',2,'Within the Mālik b. Ṣaʿṣaʿa branch every chain passes through Qatāda (candidate common link), and the four fuller texts agree on the heavens: Yūsuf 3rd, Idrīs 4th, Hārūn 5th, Mūsā 6th, Ibrāhīm 7th.',array['bukhari:3887','bukhari:3207','muslim:164a','nasai:448']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='isra-wal-miraj'),'conclusion',3,'The Abū Dharr branch (al-Zuhrī → Anas) says the narrator "did not establish their stations", fixing only Ādam in the first heaven and Ibrāhīm in the sixth. That is an apparent contradiction with the Mālik b. Ṣaʿṣaʿa branch (Ibrāhīm in the seventh) on one point only; on the other prophets it is silence, i.e. omission.',array['bukhari:349','bukhari:3342','muslim:163','bukhari:3887']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='isra-wal-miraj'),'conclusion',4,'Sharīk b. ʿAbd Allāh’s report from Anas (Bukhārī 7517) places Idrīs in the 2nd, Hārūn in the 4th, Ibrāhīm in the 6th and Mūsā in the 7th heaven, and says the event happened "before revelation came to him". Both diverge from every other route in this family.',array['bukhari:7517']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='isra-wal-miraj'),'conclusion',5,'Nasāʾī 450 (Yazīd b. Abī Mālik → Anas) swaps Hārūn (4th) and Idrīs (5th) relative to the Mālik b. Ṣaʿṣaʿa branch, and is the only member besides Muslim 162a (Thābit → Anas) that names Bayt al-Maqdis.',array['nasai:450','muslim:162a']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='isra-wal-miraj'),'conclusion',6,'Size of each reduction in the prayers: by ten in Bukhārī 3887 (Mālik b. Ṣaʿṣaʿa route), by five in Muslim 162a (Thābit → Anas), and "shaṭrahā" (a portion) in the five al-Zuhrī → Anas texts. This is labelled divergent, not contradictory, because "shaṭr" can mean a part and every version ends at five prayers.',array['bukhari:3887','muslim:162a','bukhari:349','muslim:163','nasai:449','ibnmajah:1399']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='isra-wal-miraj'),'conclusion',7,'Starting point: al-Ḥaṭīm/al-Ḥijr (Bukhārī 3887), "at the House between sleeping and waking" (Mālik b. Ṣaʿṣaʿa routes), the roof of his house opened in Mecca (Abū Dharr), and the mosque of the Kaʿba (Sharīk). These descriptions are compatible or complementary; none of them negates another.',array['bukhari:3887','bukhari:3207','bukhari:349','bukhari:7517']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='isra-wal-miraj'),'uncertainty',1,'Heaven placements are extracted by rule from the Arabic (name-in-ordinal / ordinal-then-name / met-after-ordinal). They are candidates until a reviewer checks each one against the text.','grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='isra-wal-miraj'),'uncertainty',2,'Nasāʾī 449 and Ibn Mājah 1399 (Yūnus → al-Zuhrī → Anas) are abridgements that, in the fuller Bukhārī/Muslim versions, belong to the Abū Dharr report. The abridged text does not name Abū Dharr, so they stay in the "Anas (direct)" branch.','grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='isra-wal-miraj'),'uncertainty',3,'Isnad names are auto-extracted text chunks, not rijāl identifications; al-Zuhrī appears both as "ابن شهاب" and "الزهري".','grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='isra-wal-miraj'),'uncertainty',4,'Shīʿī collections (al-Kāfī, al-Amālī, al-Tawḥīd, Man lā yaḥḍuruh) contain mi’rāj reports that match the phrase search. They are not on sunnah.com, so they are not verified at this standard and are not included.','grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='isra-wal-miraj'),'uncertainty',5,'Single-episode fragments (milk and wine, Moses praying in his grave, cupping, the vision verse 17:60) are listed as excluded, not compared.','grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='isra-wal-miraj'),'uncertainty',6,'Narrative group 2 cites "Muslim 316/321" (QuranHikma running numbers); sunnah.com numbers them 162a and 164a.','grok-bot') on conflict do nothing;
insert into public.hadith_quran_links(family_id,sura_id,aya_from,aya_to,relation,evidence_member_id,evidence_arabic,verification_status) values ((select id from public.hadith_families where slug='isra-wal-miraj'),53,8,9,'explains',(select id from public.hadith_family_members where family_id=(select id from public.hadith_families where slug='isra-wal-miraj') and hadith_corpus_canonical_id=7543),'قاب قوسين او ادني','candidate') on conflict do nothing;
insert into public.hadith_quran_links(family_id,sura_id,aya_from,aya_to,relation,evidence_member_id,evidence_arabic,verification_status) values ((select id from public.hadith_families where slug='isra-wal-miraj'),17,1,1,'thematic',null,null,'candidate') on conflict do nothing;
